uniform float amzp_radius;
uniform float amzp_quality;
uniform float amzp_exposure;
uniform float amzp_blendMode;
uniform float amzp_mixAmount;

    const float PI = 3.14159265358979323846;

    float4 sampleTex(int t, float2 uv){ return amzTexture(t, uv); }


    float4 blurInternal(int tex, float2 texOffset, float2 st, float numBlurPixelsPerSide)
    {
      if(numBlurPixelsPerSide <= 0.0) return sampleTex(tex, st);

       float3 incrementalGaussian;
      float adjSigma = numBlurPixelsPerSide / 2.14596602;
      incrementalGaussian.x = 1.0 / (sqrt(2.0 * PI) * max(adjSigma, 1e-4));
      incrementalGaussian.y = exp(-0.5 / (max(adjSigma, 1e-4) * max(adjSigma, 1e-4)));
      incrementalGaussian.z = incrementalGaussian.y * incrementalGaussian.y;

      float4 avgValue = sampleTex(tex, st) * incrementalGaussian.x;
       float coefficientSum = incrementalGaussian.x;

      for (float i = 1.0; i <= 256.0; i += 2.0) {
        if (i > numBlurPixelsPerSide) break;
        float offset0 = i;
        float offset1 = i + 1.0;

        incrementalGaussian.xy *= incrementalGaussian.yz;
        coefficientSum += (2.0 * incrementalGaussian.x);
        float weight0 = incrementalGaussian.x;
        incrementalGaussian.xy *= incrementalGaussian.yz;
        coefficientSum += (2.0 * incrementalGaussian.x);
        float weight1 = incrementalGaussian.x;
        float weightL = weight0 + weight1;
        float offsetL = (offset0*weight0 + offset1*weight1) / max(weightL, 1e-6);
        float2 stL = st - offsetL * texOffset;
        float2 stR = st + offsetL * texOffset;
        avgValue += sampleTex(tex, stL) * weightL;
        avgValue += sampleTex(tex, stR) * weightL;
      }
      return avgValue / max(coefficientSum, 1e-6);
    }

    float tapsForQualityF(float q){
      return (q < 1.5) ? 6.0 : ((q < 2.5) ? 10.0 : 14.0);
    }

    void amzRender(){
      float2 uv = amzScreenNorm();


      float taps = tapsForQualityF(float(int(amzp_quality)));
      float kernelSize = amzp_radius * 0.5 * (taps/10.0);

      if (amzPass == 0) {

        float2 to = float2(1.0 / getTexSize((screen.zw/1.0)).x, 0.0);
        amzOutput = blurInternal(0, to, uv, kernelSize);
        return;
      }
      if (amzPass == 1) {

        float2 to = float2(0.0, 1.0 / getTexSize((screen.zw/1.0)).y);
        amzOutput = blurInternal(1, to, uv, kernelSize);
        return;
      }


      float4 src = sampleTex(0, uv);
      float3 blurred = sampleTex(2, uv).rgb * amzp_exposure;

      int bm = int(int(amzp_blendMode));
      float3 outRGB;
      if (bm == 1) {

        outRGB = mix(src.rgb, blurred, clamp(amzp_mixAmount, 0.0, 1.0));
      } else if (bm == 2) {

        outRGB = src.rgb + blurred * clamp(amzp_mixAmount, 0.0, 1.0);
      } else {

        float3 scr = 1.0 - (1.0 - src.rgb) * (1.0 - clamp(blurred, 0.0, 100.0));
        outRGB = mix(src.rgb, scr, clamp(amzp_mixAmount, 0.0, 1.0));
      }

      amzOutput = float4(outRGB, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
